grid = [
    [6, 6, 6, 3, 6, 6, 6],
    [7, 6, 6, 3, 6, 6, 6],
    [6, 7, 6, 3, 7, 6, 6],
    [3, 3, 3, 3, 3, 3, 3],
    [6, 6, 7, 3, 6, 6, 6],
    [7, 6, 6, 3, 6, 6, 6],
    [6, 6, 6, 3, 7, 7, 6],
    [3, 3, 3, 3, 3, 3, 3],
    [6, 6, 6, 3, 6, 6, 6],
    [6, 7, 6, 3, 6, 6, 6],
    [6, 6, 6, 3, 7, 6, 6],
    [3, 3, 3, 3, 3, 3, 3],
    [6, 6, 6, 3, 7, 6, 6],
    [6, 6, 6, 3, 6, 6, 6],
    [6, 6, 6, 3, 6, 6, 6]
]

# Check (row + col) % 3
print("Checking (r+c) % 3 for 7s:")
sum_mod_counts = {}
for r in range(15):
    for c in range(7):
        if grid[r][c] == 7:
            mod = (r + c) % 3
            sum_mod_counts[mod] = sum_mod_counts.get(mod, 0) + 1
print(sum_mod_counts)

# Check (row - col) % 3
print("\nChecking (r-c) % 3 for 7s:")
diff_mod_counts = {}
for r in range(15):
    for c in range(7):
        if grid[r][c] == 7:
            mod = (r - c) % 3
            diff_mod_counts[mod] = diff_mod_counts.get(mod, 0) + 1
print(diff_mod_counts)

# Check diagonals within 3x3 regions
# In a 3x3 region, diagonals would be r-c == 0 (main), r-c == 1, r-c == -1

# Let me look at what regions have 7s and their positions within the region
print("\n7s positions within their 3x3 regions (relative to region TL):")
region_positions = []
for vr_start, vr_end in [(0, 2), (4, 6), (8, 10), (12, 14)]:
    for hc_start, hc_end in [(0, 2), (4, 6)]:
        for r in range(vr_start, vr_end+1):
            for c in range(hc_start, hc_end+1):
                if grid[r][c] == 7:
                    rel_r = r - vr_start
                    rel_c = c - hc_start
                    region_positions.append((vr_start, vr_end, hc_start, hc_end, rel_r, rel_c))

for pos in region_positions:
    print(f"Region {pos[0]}-{pos[1]}, {pos[2]}-{pos[3]}: 7 at ({pos[4]},{pos[5]})")

